INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `description`, `short_description`) VALUES
(3, 22347, 'en', 'Кремава дамска шапка федора', '<p>Дамска шапка федора във винтидж стил, ръчно д<span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\">екорирана с лента от гросгрейн и </span></p>\r\n<p><span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\">комбинация от бели, светло сини и пепеливо розови цветя.&nbsp;</span><br /><br />Материал: естествен филц</p>\r\n<p>&nbsp;</p>\r\n<p><span class=\"\">Всяка шапка е ръчно изработена и може да бъде персонализирана, </span></p>\r\n<p><span class=\"\">за да отговаря на вашия избор на цвят, за да</span> пасва безпроблемно на вашия стил.</p>\r\n<p>&nbsp;</p>\r\n<p><img src=\"/storage/media/hwpUqwzKHCswu3oS1tI3cedb6pf2olNNFeVJV5be.png\" alt=\"\" width=\"1098\" height=\"317\" /></p>\r\n<p><img src=\"/storage/media/jYsAdwnMPOuF2IW5G16pPHtdnwZXj1sCIftHRXxW.png\" alt=\"\" width=\"1098\" height=\"300\" /></p>', NULL),
(4, 22348, 'en', 'Черна дамска шапка федора', '<p>Дамска шапка федора във винтидж стил, ръчно д<span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\">екорирана с </span><span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\">комбинация от кремави,</span></p>\r\n<p><span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\"> зелени и бели цветя.&nbsp;</span></p>\r\n<p>Материал: естествен филц</p>\r\n<p>&nbsp;</p>\r\n<p><span class=\"\">Всяка шапка е ръчно изработена и може да бъде персонализирана, </span></p>\r\n<p><span class=\"\">за да отговаря на вашия избор на цвят, за да</span> пасва безпроблемно на вашия стил.</p>\r\n<p><img src=\"/storage/media/9zcGAaVroBIjc8GtgdjOsQEyFr48L59dzH0CVNMI.png\" alt=\"\" width=\"1098\" height=\"317\" /><img src=\"/storage/media/PRsHaGarWemRG0RhYTYk4Sp35Zd9yBPHubCqwlOM.png\" alt=\"\" width=\"1098\" height=\"300\" /></p>', NULL),
(5, 22349, 'en', 'Циклама шапка федора', '<p>Дамска шапка федора във винтидж стил, ръчно д<span class=\"VIpgJd-yAWNEb-VIpgJd-fmcmS-sn54Q\">екорирана в</span> комбинация от розови,</p>\r\n<p>цикламени и пепеливо розови цветя.&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Материал: естествен филц</p>\r\n<p>&nbsp;</p>\r\n<p><span class=\"\">Всяка шапка е ръчно изработена и може да бъде персонализирана, </span></p>\r\n<p><span class=\"\">за да отговаря на вашия избор на цвят, за да</span> пасва безпроблемно на вашия стил.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><img src=\"/storage/media/5HCmDD1ji3GqNYyCIszVdM3OpAfncdR7RAtZgEj8.png\" alt=\"\" width=\"1098\" height=\"317\" /></p>\r\n<p><img src=\"/storage/media/2ti9xgxVkaiinEmuSsSckiubT7V9I8uuPJEnOfXc.png\" alt=\"\" width=\"1098\" height=\"300\" /></p>', NULL),
(6, 22350, 'en', 'Дамска сатенена диадема зелена', '<p>&nbsp;</p>\r\n<p>Дамска сатенена диадема скрънчи&nbsp;</p>\r\n<p>Ръчно изработена диадема от висококачествен сатен, без разбридване и оставяне на петна по него.</p>\r\n<p>Всяка диадема се изработва в два размера &ndash; дамски и детски</p>\r\n<ul>\r\n<li>широчина &ndash; 4 см.</li>\r\n<li>универсален размер</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Всички наши аксесоари за изработени от високачествени и хипоалергични материали и материи.</p>', NULL),
(7, 22351, 'en', 'Оранжева дамска сатенена диадема', '<p>&nbsp;</p>\r\n<p>Дамска сатенена диадема скрънчи&nbsp;</p>\r\n<p>Ръчно изработена диадема от висококачествен сатен, без разбридване и оставяне на петна по него.</p>\r\n<p>Всяка диадема се изработва в два размера &ndash; дамски и детски</p>\r\n<ul>\r\n<li>широчина &ndash; 4 см.</li>\r\n<li>универсален размер</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Всички наши аксесоари за изработени от високачествени и хипоалергични материали и материи.</p>', NULL),
(8, 22352, 'en', 'Циклама дамска сатенена диадема', '<p>Дамска сатенена диадема скрънчи&nbsp;</p>\r\n<p>Ръчно изработена диадема от висококачествен сатен, без разбридване и оставяне на петна по него.</p>\r\n<p>Всяка диадема се изработва в два размера &ndash; дамски и детски</p>\r\n<ul>\r\n<li>широчина &ndash; 4 см.</li>\r\n<li>универсален размер</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Всички наши аксесоари за изработени от високачествени и хипоалергични материали и материи.</p>', NULL),
